 function save(){if(scene?.hero)position={x:scene.hero.x,y:scene.hero.y};try{localStorage.setItem(SAVE,JSON.stringify({...position,stage,dialogueTone}));$('save-state').textContent='Progreso guardado en este dispositivo';}catch{$('save-state').textContent='No se pudo guardar el progreso en este navegador'}}
