 function dialogue(node=0){scene?.stop();const name=character?.name?.trim()||'viajero';const nodes={
  0:{text:`Alto, ${name}. Las puertas cierran al caer la noche. No pareces un mercader… ¿Qué te trae a Valdara?`,options:[['Mostrar la carta sellada',1],['¿Por qué están cerrando las puertas?',4]]},
  1:{text:'Ese sello… Mi hermano recibió uno igual. Partió hacia el monasterio hace seis días y no volvió. ¿La ceniza de tu carta también sigue caliente?',options:[['Sí. Dice que mi nombre está en una puerta.',2,()=>{dialogueTone='open'}],['No estoy seguro. Prefiero no hablar de la carta.',6,()=>{dialogueTone='guarded'}]]},
  2:{text:dialogueTone==='guarded'?'Elara espera un momento antes de confiar en ti. «Entonces necesitarás respuestas antes de cruzar. El campanero puede dártelas, pero no puedo prometerte que te reciba».':'Entonces no llegaste por casualidad. Hace trece años que las campanas no suenan, pero esta mañana oí una bajo la ciudad. Busca al campanero cuando entres. Él sabía qué estaba esperando mi hermano.',options:[['Iré a buscarlo. Déjame pasar.',3],['No puedo prometerlo. Primero debo entender la carta.',6,()=>{dialogueTone='guarded'}]]},
  3:{text:'Te daré paso. Acércate a la puerta y avisaré al centinela. Y si encuentras a Darien… dile que su hermana todavía lo espera.',options:[['Acercarme a la puerta',-2],['Antes quiero revisar mis cosas.',-1]]},
  4:{text:'Hay gente desapareciendo. Primero los viajeros; ahora también los nuestros. La orden dice que es por seguridad. Yo digo que tienen miedo de lo que hay dentro.',options:[['Hay algo que debes ver. Mostrar la carta.',1],['Entiendo. Volveré en un momento.',-1]]},
  5:{text:'El centinela está avisado. Ve a la puerta. Recuerda: busca al campanero, y pregunta por Darien.',options:[['Ir a la puerta',-2],['Seguir explorando el puente',-1]]},
  6:{text:'Elara guarda la carta sin tocarla. «No tienes que contármelo todo. Pero si buscas respuestas, necesitarás que alguien te reconozca cuando cruces».',options:[['Compartir la carta y seguir adelante',3,()=>{dialogueTone='open'}],['Pedir un momento para ordenar tus ideas',5]]}
 };
 if(node===1)stage=Math.max(stage,1);if(node===3)stage=Math.max(stage,2);quest();save();const data=nodes[node]||nodes[0];$('speech-text').textContent=data.text;$('answers').replaceChildren(...data.options.map(([label,next,effect])=>{const b=document.createElement('button');b.type='button';b.textContent='› '+label;b.onclick=()=>{effect?.();save();if(next<0){$('dialogue').close();if(next===-2)setTimeout(()=>scene?.goGate(),0)}else dialogue(next)};return b}));if(!$('dialogue').open)$('dialogue').showModal()}
