this.guardZone=this.add.zone(World.guard.x,World.guard.y-55,95,130).setInteractive({useHandCursor:true}).setDepth(1000);this.guardZone.on('pointerdown',(_p,_x,_y,event)=>{event.stopPropagation();this.goTalk()});this.nameTag=this.add.text(position.x,position.y-96,'Viajero',{fontFamily:'Georgia',fontSize:'17px',color:'#fff8dd',stroke:'#273b2f',strokeThickness:4}).setOrigin(.5,1).setDepth(1100);this.guardLabel=this.add.text(World.guard.x,World.guard.y-114,'Elara',{fontFamily:'Georgia',fontSize:'17px',color:'#fff4c9',stroke:'#283d30',strokeThickness:4}).setOrigin(.5,1).setDepth(1100);this.cues=window.CenizasInteractionCues.create(this);this.nameTag.setVisible(false);
this.cameras.main.setBounds(0,0,1536,1024);this.resize(this.scale.gameSize);this.cameras.main.startFollow(this.hero,true,.08,.08);this.cameras.main.centerOn(this.hero.x,this.hero.y);this.scale.on('resize',this.resize,this);this.keys=this.input.keyboard.addKeys('W,A,S,D,UP,DOWN,LEFT,RIGHT,E,C,J');this.input.keyboard.on('keydown',e=>{if(modalOpen()||e.repeat)return;if(e.code==='KeyE')this.goTalk();if(e.code==='KeyC')openModal('sheet-modal');if(e.code==='KeyJ')openModal('journal-modal')});this.time.addEvent({delay:3000,loop:true,callback:save});refreshCharacter();quest();$('loading').classList.add('hidden');this.ready=true;
